From 1305700bab347d771f4dfd8748b99b569e690e2c Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Wed, 25 Nov 2026 22:24:33 +0100
Subject: [PATCH] containments/desktop: add a Duplicate Here action

Folder View had no way to duplicate items, unlike Dolphin. Add Dolphin's
"Duplicate Here" action to the item context menu and to Ctrl+D, copying
each selected item next to itself with "copy" added before its extension.

BUG: 448799
---
 .../package/contents/ui/FolderView.qml        |  2 +
 .../desktop/plugins/folder/foldermodel.cpp    | 52 +++++++++++++++++++
 .../desktop/plugins/folder/foldermodel.h      |  1 +
 3 files changed, 55 insertions(+)

diff --git a/containments/desktop/package/contents/ui/FolderView.qml b/containments/desktop/package/contents/ui/FolderView.qml
index b858d16f7a..ce7af78b69 100644
--- a/containments/desktop/package/contents/ui/FolderView.qml
+++ b/containments/desktop/package/contents/ui/FolderView.qml
@@ -1040,6 +1040,8 @@ FocusScope {
                         dir.paste();
                     } else if (event.matches(StandardKey.Cut)) {
                         dir.cut();
+                    } else if (event.key === Qt.Key_D && event.modifiers === Qt.ControlModifier) {
+                        dir.duplicate();
                     } else if (event.matches(StandardKey.Undo)) {
                         dir.undo();
                     } else if (event.matches(StandardKey.Refresh)) {
diff --git a/containments/desktop/plugins/folder/foldermodel.cpp b/containments/desktop/plugins/folder/foldermodel.cpp
