     refresh->setShortcut(QKeySequence(QKeySequence::Refresh));
     connect(refresh, &QAction::triggered, this, &FolderModel::refresh);

+    QAction *duplicate = new QAction(QIcon::fromTheme(QStringLiteral("edit-duplicate")), i18nc("@action:inmenu File", "Duplicate Here"), this);
+    duplicate->setShortcut(Qt::CTRL | Qt::Key_D);
+    connect(duplicate, &QAction::triggered, this, &FolderModel::duplicate);
+
     QAction *rename = KStandardAction::renameFile(this, &FolderModel::requestRename, this);
     QAction *trash = KStandardAction::moveToTrash(this, &FolderModel::moveSelectedToTrash, this);
     QAction *del = KStandardAction::deleteFile(this, &FolderModel::deleteSelected, this);
@@ -1871,6 +1875,7 @@ void FolderModel::createActions()
     m_actionCollection.addAction(QStringLiteral("paste"), paste);
     m_actionCollection.addAction(QStringLiteral("pasteto"), pasteTo);
     m_actionCollection.addAction(QStringLiteral("refresh"), refresh);
+    m_actionCollection.addAction(QStringLiteral("duplicate"), duplicate);
     m_actionCollection.addAction(QStringLiteral("rename"), rename);
     m_actionCollection.addAction(QStringLiteral("remove"), remove);
     m_actionCollection.addAction(QStringLiteral("trash"), trash);
@@ -2011,6 +2016,11 @@ void FolderModel::updateActions()
         }
     }

+    if (QAction *duplicate = m_actionCollection.action(QStringLiteral("duplicate"))) {
+        duplicate->setEnabled(itemProperties.supportsReading() && KFileItemListProperties(KFileItemList() << rootItem()).supportsWriting());
+        duplicate->setVisible(!isTrash && !isTrashLink);
+    }
+
     if (QAction *rename = m_actionCollection.action(QStringLiteral("rename"))) {
         rename->setEnabled(itemProperties.supportsMoving());
         rename->setVisible(!isTrash);
@@ -2108,6 +2118,7 @@ void FolderModel::openContextMenu(QQuickItem *visualParent, Qt::KeyboardModifier
             menu->addAction(m_actionCollection.action(QStringLiteral("paste")));
         }

+        menu->addAction(m_actionCollection.action(QStringLiteral("duplicate")));
         menu->addAction(m_actionCollection.action(QStringLiteral("rename")));

         if (!isTrashLink) {
@@ -2281,6 +2292,47 @@ void FolderModel::pasteTo()
     KIO::paste(QApplication::clipboard()->mimeData(), urls.first());
 }

+void FolderModel::duplicate()
+{
+    if (!m_selectionModel->hasSelection()) {
+        return;
+    }
+
+    if (QAction *action = m_actionCollection.action(QStringLiteral("duplicate"))) {
+        if (!action->isEnabled()) {
+            return;
+        }
+    }
+
+    const QMimeDatabase db;
+
+    // Append "copy" to the file name, before the extension if there is one, as Dolphin does
+    for (const QModelIndex &index : m_selectionModel->selectedIndexes()) {
+        const KFileItem item = itemForIndex(index);
+        if (item.isNull()) {
+            continue;
+        }
+
+        const QUrl originalUrl = item.url();
+        const QString directoryPath = originalUrl.adjusted(QUrl::RemoveFilename).path();
+        const QString fileName = item.name();
+        const QString extension = db.suffixForFileName(fileName);
+
+        QUrl duplicateUrl = originalUrl;
+        if (extension.isEmpty()) {
+            duplicateUrl.setPath(directoryPath + i18nc("<filename> copy", "%1 copy", fileName));
+        } else {
+            const int extensionLength = extension.size() + 1;
+            duplicateUrl.setPath(directoryPath + i18nc("<filename> copy", "%1 copy", fileName.chopped(extensionLength)) + fileName.right(extensionLength));
+        }
+
+        KIO::CopyJob *job = KIO::copyAs(originalUrl, duplicateUrl);
+        job->setAutoRename(true);
+        job->setUiDelegate(new KNotificationJobUiDelegate(KJobUiDelegate::AutoHandlingEnabled));
+        KIO::FileUndoManager::self()->recordCopyJob(job);
+    }
+}
+
 void FolderModel::refresh()
 {
     m_errorString.clear();
diff --git a/containments/desktop/plugins/folder/foldermodel.h b/containments/desktop/plugins/folder/foldermodel.h
